class Solution { public int[] secondGreaterElement(int[] nums){int[] answer=new int[nums.length];Arrays.fill(answer,-1);Deque<Integer> first=new ArrayDeque<>(),second=new ArrayDeque<>();for(int i=0;i<nums.length;i++){while(!second.isEmpty()&&nums[second.peek()]<nums[i])answer[second.pop()]=nums[i];List<Integer> moved=new ArrayList<>();while(!first.isEmpty()&&nums[first.peek()]<nums[i])moved.add(first.pop());for(int j=moved.size()-1;j>=0;j--)second.push(moved.get(j));first.push(i);}return answer;} }
